for (size_t i = start; i < end; i++) {
    Particle *pi = &particles[i];
    pi->force = std::vector<glm::vec3>(0);
    glm::ivec3 cell = getCell(pi, h);
    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            for (int z = -1; z <= 1; z++) {
                uint32_t cellHash = getHash(cell + glm::ivec3(x, y, z));
                uint32_t pjIndex = particleTable[cellHash];
                if (pjIndex == NO_PARTICLE) {
                    continue;
                }
                while (pjIndex < particleCount) {
                    if (pjIndex == i) {
                        pjIndex++;
                        continue;
                    }
                    Particle *pj = &particles[pjIndex];
                    if (pj->hash != cellHash) {
                        break;
                    }
                    float dist2 = glm::length2(pj->position - pi->position);
                    if (dist2 < h2 && pi != pj) {
                        // Apply pressure force
                        glm::vec3 dir = glm::normalize(pj->position - pi->position);
                        glm::vec3 pressureForce = -dir * mass * (pi->pressure + pj->pressure) / (2 * pj->density) * spikyGrad;
                        pressureForce *= std::pow(h - std::sqrt(dist2), 2);
                        pi->force += pressureForce;

                        // Apply viscosity force
                        glm::vec3 velocityDif = pj->velocity - pi->velocity;
                        glm::vec3 viscoForce = viscosity * mass * (velocityDif / pj->density) * spikyLap * (h - std::sqrt(dist2));
                        pi->force += viscoForce;
                    }
                    pjIndex++;
                }
            }
        }
    }
}

